-- Fantasy Friends executable migration 20261115000013_privilege_verification
-- Generated by scripts/promote-migrations.mjs from supabase/design/migrations/010_privilege_verification.sql
-- Do not edit by hand: the guard re-derives this file and fails on drift.

-- PHASE 2B.2 DESIGN DRAFT. NOT A DEPLOYABLE MIGRATION. Do not place under
-- supabase/migrations or apply to a Supabase project.
--
-- Verification migration: fails the deployment rather than passing silently if
-- the effective privileges are not the reviewed ones.
--
-- This is deliberately assertions only. It grants nothing and changes no policy.
-- A failing assertion aborts the migration transaction, so a drifted privilege
-- model cannot be recorded as successfully applied.

do $$
declare offenders text;
begin
  -- 0. The reviewed objects must exist. A missing table means an earlier
  --    migration silently did nothing, which must fail the deployment.
  select string_agg(missing, ', ' order by missing) into offenders
  from unnest(array['match_correction_attempts','match_result_forks','scoring_run_sources','match_corrections']) missing
  where to_regclass('public.' || missing) is null;
  if offenders is not null then
    raise exception 'reviewed tables are missing: %', offenders using errcode = '42501';
  end if;

  -- 1. anon must hold no table privilege in public at all.
  select string_agg(format('%I:%s', c.relname, p.privilege_type), ', ' order by c.relname)
    into offenders
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  cross join lateral aclexplode(coalesce(c.relacl, '{}'::aclitem[])) p
  where n.nspname = 'public' and c.relkind in ('r', 'p')
    and p.grantee = (select oid from pg_roles where rolname = 'anon');
  if offenders is not null then
    raise exception 'anon holds table privileges in public: %', offenders using errcode = '42501';
  end if;

  -- 2. authenticated must hold exactly SELECT on every public table.
  select string_agg(format('%I:%s', c.relname, p.privilege_type), ', ' order by c.relname)
    into offenders
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  cross join lateral aclexplode(coalesce(c.relacl, '{}'::aclitem[])) p
  where n.nspname = 'public' and c.relkind in ('r', 'p')
    and p.grantee = (select oid from pg_roles where rolname = 'authenticated')
    and p.privilege_type <> 'SELECT';
  if offenders is not null then
    raise exception 'authenticated holds non-SELECT privileges in public: %', offenders using errcode = '42501';
  end if;

  -- 3. Every public table must have RLS enabled; table owners bypass RLS and
  --    FORCE is not used, so ownership is asserted separately in (6).
  select string_agg(c.relname, ', ' order by c.relname) into offenders
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r', 'p') and not c.relrowsecurity;
  if offenders is not null then
    raise exception 'public tables without row level security: %', offenders using errcode = '42501';
  end if;

  -- 4. No SECURITY DEFINER function in an exposed schema may be executable by
  --    PUBLIC or anon, and every definer function must pin search_path.
  select string_agg(format('%s.%I', n.nspname, f.proname), ', ' order by n.nspname, f.proname)
    into offenders
  from pg_proc f join pg_namespace n on n.oid = f.pronamespace
  where n.nspname in ('public', 'ff_private') and f.prosecdef
    and (has_function_privilege('anon', f.oid, 'execute')
         or exists (select 1 from aclexplode(coalesce(f.proacl, acldefault('f', f.proowner))) a
                    where a.grantee = 0 and a.privilege_type = 'EXECUTE'));
  if offenders is not null then
    raise exception 'security definer functions reachable by anon or PUBLIC: %', offenders using errcode = '42501';
  end if;

  select string_agg(format('%s.%I', n.nspname, f.proname), ', ' order by n.nspname, f.proname)
    into offenders
  from pg_proc f join pg_namespace n on n.oid = f.pronamespace
  where n.nspname in ('public', 'ff_private') and f.prosecdef
    and not exists (select 1 from unnest(coalesce(f.proconfig, '{}'::text[])) c where c like 'search_path=%');
  if offenders is not null then
    raise exception 'security definer functions without a pinned search_path: %', offenders using errcode = '42501';
  end if;

  -- 5. Only the ten reviewed read helpers may be executable by authenticated.
  select string_agg(f.proname, ', ' order by f.proname) into offenders
  from pg_proc f join pg_namespace n on n.oid = f.pronamespace
  where n.nspname = 'ff_private'
    and has_function_privilege('authenticated', f.oid, 'execute')
    and f.proname not in ('is_member','is_leader','is_organizer','owns_team','can_read_lineup',
                          'can_read_revision','can_read_match','can_read_suggestion','can_read_image',
                          'is_match_organizer');
  if offenders is not null then
    raise exception 'workflow functions executable by authenticated: %', offenders using errcode = '42501';
  end if;

  -- 6. The definer owner must be a non-login role that is not a client role.
  --
  --    It MUST have BYPASSRLS. Phase 2B.3 measured that a nobypassrls definer
  --    makes all ten read helpers return FALSE for legitimate users, silently:
  --    the policies are `to authenticated`, the definer is not `authenticated`,
  --    and each helper is `exists(... where user_id = auth.uid())`, so the inner
  --    select is RLS-filtered to zero rows. This assertion is the guard that
  --    stops that model from ever being deployed. BYPASSRLS is safe here only
  --    because the role is NOLOGIN and reachable solely as a definer.
  if exists (select 1 from pg_roles where rolname = 'ff_migration_owner' and rolcanlogin) then
    raise exception 'ff_migration_owner must be NOLOGIN' using errcode = '42501';
  end if;
  if exists (select 1 from pg_roles where rolname = 'ff_migration_owner' and not rolbypassrls) then
    raise exception 'ff_migration_owner must have BYPASSRLS: a nobypassrls definer makes every read helper silently return false'
      using errcode = '42501';
  end if;
  -- The definer must not own application tables: it gets table privileges only,
  -- so it can never run DDL on the data it mediates.
  if exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
             where n.nspname = 'public' and c.relkind in ('r','p','v','m')
               and pg_get_userbyid(c.relowner) = 'ff_migration_owner') then
    raise exception 'ff_migration_owner must not own public relations' using errcode = '42501';
  end if;
  -- The definer must be able to establish the caller identity WITHOUT needing
  -- USAGE on the `auth` schema. Hosted Supabase cannot grant that USAGE: the
  -- auth schema is owned by supabase_admin and `postgres` holds USAGE without
  -- the grant option, so `grant usage on schema auth` silently no-ops (Postgres
  -- only logs 'no privileges were granted'). Asserting the unobtainable grant
  -- made this migration abort on every hosted project.
  --
  -- The requirement is therefore stated as what it actually is: the definer must
  -- not resolve anything inside `auth`. Asserting that no definer function calls
  -- auth.uid() is the invariant that makes the API work on a hosted project, and
  -- it is strictly stronger than the old check on a local one.
  if exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in ('public', 'ff_private') and p.prosecdef
      and pg_get_userbyid(p.proowner) = 'ff_migration_owner'
      and position('auth.uid()' in p.prosrc) > 0
  ) then
    raise exception 'a SECURITY DEFINER function owned by ff_migration_owner still calls auth.uid(); '
      'hosted Supabase cannot grant USAGE on the auth schema, so it would fail with 42501 at runtime. '
      'Apply 014 (definer actor identity) first.'
      using errcode = '42501';
  end if;
  -- When the actor-identity helper exists, the definer must be able to execute it.
  -- 014 owns creating it and asserts its own preconditions; this check only
  -- guards against the helper being present but unreachable.
  if to_regprocedure('ff_private.current_actor_id()') is not null
     and not has_function_privilege('ff_migration_owner', 'ff_private.current_actor_id()', 'execute') then
    raise exception 'ff_migration_owner cannot execute ff_private.current_actor_id(); the definer has no usable caller identity'
      using errcode = '42501';
  end if;

  -- 7. Storage: RLS must be enabled on storage.objects. This is an assertion, not
  --    a fix; if the migration role cannot create the storage policy the
  --    deployment must stop and use the documented owner-authorized procedure.
  if exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
             where n.nspname = 'storage' and c.relname = 'objects' and not c.relrowsecurity) then
    raise exception 'storage.objects must have row level security enabled' using errcode = '42501';
  end if;

  -- 8. The player-images policy must exist and be a SELECT-only, authenticated
  --    policy. A wider policy would be a real regression that a green build hides.
  if not exists (select 1 from pg_policies
                 where schemaname = 'storage' and tablename = 'objects'
                   and policyname = 'player_images_member_read' and cmd = 'SELECT') then
    raise exception 'storage policy player_images_member_read is missing or not SELECT-only' using errcode = '42501';
  end if;

  -- 9. No client role may be a member of the definer owner, directly or via
  --    inheritance.
  if exists (select 1 from pg_auth_members m
             join pg_roles g on g.oid = m.roleid join pg_roles u on u.oid = m.member
             where g.rolname = 'ff_migration_owner'
               and u.rolname in ('anon','authenticated','service_role','authenticator')) then
    raise exception 'a client or API role inherits ff_migration_owner' using errcode = '42501';
  end if;
end $$;
